COMMIT;

-- Verificación rápida:
SELECT COUNT(*) AS remisiones_importadas FROM remisiones;
SELECT COUNT(*) AS detalles_importados FROM detalle_remision;
SELECT COALESCE(SUM(saldo_pendiente),0) AS cartera_importada FROM remisiones;
SELECT COALESCE(SUM(total),0) AS ventas_importadas FROM remisiones;